\begin{lemma} \label{L: many yellow pw skew}
     Let \mathcal{F$ be a maximal coclique of \Gamma_{2n}$ with $n\geq 3$ and assume that the number of red spaces is \mathcal{O(q^{n^2-2})$. Then $|\mathcal{F|$ is \mathcal{O(q^{n^2+n-2})$, or there are at least $n+1$ yellow $(n-1)$-spaces in \mathcal{F$ that are pairwise skew, or there are at least $n+1$ yellow $n$-spaces in general position.
\end{lemma}

